const express = require('express');
const cors = require('cors');
const path = require('path');
const fs = require('fs');

const app = express();
const PORT = process.env.PORT || 5000;

app.use(cors());
app.use(express.json({ limit: '10mb' }));

// Reference root-level folders
const getPdfsPath = () => {
  let p = path.join(process.cwd(), 'Web Gui', 'pdfs');
  if (fs.existsSync(p)) return p;
  p = path.join(__dirname, '..', 'pdfs');
  return p;
};

const getDatasetPath = () => {
  let p = path.join(process.cwd(), 'Dataset', 'yokdil');
  if (fs.existsSync(p)) return p;
  p = path.join(__dirname, '..', '..', 'Dataset', 'yokdil');
  return p;
};

const pdfsDir = getPdfsPath();
const datasetDir = getDatasetPath();
const resolveLecturesDir = () => {
  const genelLectures = path.join(datasetDir, 'genel', 'lectures');
  if (fs.existsSync(genelLectures)) return genelLectures;
  return path.join(datasetDir, 'fen', 'konu_anlatimi');
};
const lecturesDir = resolveLecturesDir();
const questionsDir = datasetDir;

const getQuestionsDir = (req) => {
  const category = req.params.category || req.query.category || 'fen';
  const catPath = path.join(datasetDir, category);
  return fs.existsSync(catPath) ? catPath : path.join(datasetDir, 'fen');
};

// Serve PDF files statically
app.use('/pdfs', express.static(pdfsDir));

// Serve dataset statically from root
const getDatasetRootPath = () => {
  let p = path.join(process.cwd(), 'Dataset');
  if (fs.existsSync(p)) return p;
  p = path.join(__dirname, '..', '..', 'Dataset');
  return p;
};
app.use('/dataset', express.static(getDatasetRootPath()));


// Serve the generated clean PDF from the root workspace folder
app.get('/pdfs/YOKDIL_Temiz_Soru_Kitapcigi.pdf', (req, res) => {
  const pdfPath = path.join(pdfsDir, 'YÖKDİL_Temiz_Soru_Kitapçığı.pdf');
  if (fs.existsSync(pdfPath)) {
    res.sendFile(pdfPath);
  } else {
    res.status(404).send('PDF file not found');
  }
});

